module.exports = "import React from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\n\nimport {\n  EuiBasicTable,\n  EuiLink,\n  EuiHealth,\n} from '../../../../../src/components';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport const Table = () => {\n  const columns = [\n    {\n      field: 'firstName',\n      name: 'First Name',\n      sortable: true,\n      'data-test-subj': 'firstNameCell',\n      mobileOptions: {\n        render: item => (\n          <span>\n            {item.firstName}{' '}\n            <EuiLink href=\"#\" target=\"_blank\">\n              {item.lastName}\n            </EuiLink>\n          </span>\n        ),\n        header: false,\n        truncateText: false,\n        enlarge: true,\n        fullWidth: true,\n      },\n    },\n    {\n      field: 'lastName',\n      name: 'Last Name',\n      truncateText: true,\n      render: name => (\n        <EuiLink href=\"#\" target=\"_blank\">\n          {name}\n        </EuiLink>\n      ),\n      mobileOptions: {\n        show: false,\n      },\n    },\n    {\n      field: 'github',\n      name: 'Github',\n    },\n    {\n      field: 'dateOfBirth',\n      name: 'Date of Birth',\n      dataType: 'date',\n      render: date => formatDate(date, 'dobLong'),\n    },\n    {\n      field: 'nationality',\n      name: 'Nationality',\n      render: countryCode => {\n        const country = store.getCountry(countryCode);\n        return `${country.flag} ${country.name}`;\n      },\n    },\n    {\n      field: 'online',\n      name: 'Online',\n      dataType: 'boolean',\n      render: online => {\n        const color = online ? 'success' : 'danger';\n        const label = online ? 'Online' : 'Offline';\n        return <EuiHealth color={color}>{label}</EuiHealth>;\n      },\n    },\n  ];\n\n  const items = store.users.filter((user, index) => index < 10);\n\n  const getRowProps = item => {\n    const { id } = item;\n    return {\n      'data-test-subj': `row-${id}`,\n      className: 'customRowClass',\n      onClick: () => console.log(`Clicked row ${id}`),\n    };\n  };\n\n  const getCellProps = (item, column) => {\n    const { id } = item;\n    const { field } = column;\n    return {\n      className: 'customCellClass',\n      'data-test-subj': `cell-${id}-${field}`,\n      textOnly: true,\n    };\n  };\n\n  return (\n    <EuiBasicTable\n      items={items}\n      columns={columns}\n      rowProps={getRowProps}\n      cellProps={getCellProps}\n    />\n  );\n};\n"