module.exports = "import React, { Component } from 'react';\n\nimport moment from 'moment';\n\nimport {\n  EuiDatePicker,\n  EuiFormRow,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      startDate: moment(),\n    };\n\n    this.handleChange = this.handleChange.bind(this);\n  }\n\n  handleChange(date) {\n    this.setState({\n      startDate: date,\n    });\n  }\n\n  render() {\n    return (\n      <div>\n        <EuiFormRow label=\"Time select on\">\n          <EuiDatePicker\n            showTimeSelect\n            selected={this.state.startDate}\n            onChange={this.handleChange}\n            dateFormat=\"MM/DD/YYYY HH:mm.ss.SSS\"\n          />\n        </EuiFormRow>\n\n        <EuiSpacer />\n\n        <EuiFormRow label=\"Time select off\">\n          <EuiDatePicker\n            selected={this.state.startDate}\n            onChange={this.handleChange}\n            dateFormat=\"MM/DD/YYYY\"\n          />\n        </EuiFormRow>\n\n        <EuiSpacer />\n\n        <EuiFormRow label=\"Only time select, 24 hour clock\">\n          <EuiDatePicker\n            showTimeSelect\n            showTimeSelectOnly\n            selected={this.state.startDate}\n            onChange={this.handleChange}\n            dateFormat=\"HH:mm\"\n            timeFormat=\"HH:mm\"\n          />\n        </EuiFormRow>\n\n        <EuiSpacer />\n\n        <EuiFormRow label=\"Inject additional times into the list\">\n          <EuiDatePicker\n            showTimeSelect\n            showTimeSelectOnly\n            selected={this.state.startDate}\n            onChange={this.handleChange}\n            dateFormat=\"hh:mm a\"\n            injectTimes={[\n              moment()\n                .hours(0)\n                .minutes(1),\n              moment()\n                .hours(0)\n                .minutes(5),\n              moment()\n                .hours(23)\n                .minutes(59),\n            ]}\n          />\n        </EuiFormRow>\n      </div>\n    );\n  }\n}\n"