module.exports = "import React, { Component } from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\nimport {\n  EuiLink,\n  EuiHealth,\n  EuiButton,\n  EuiInMemoryTable,\n  EuiEmptyPrompt,\n} from '../../../../../src/components';\nimport { Random } from '../../../../../src/services/random';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst random = new Random();\n\nconst store = createDataStore();\n\nconst noItemsFoundMsg = 'No users match search criteria';\n\nexport class Table extends Component {\n  constructor(props) {\n    super(props);\n    this.state = {\n      loading: false,\n      users: [],\n      message: (\n        <EuiEmptyPrompt\n          title={<h3>No users</h3>}\n          titleSize=\"xs\"\n          body=\"Looks like you don&rsquo;t have any users. Let&rsquo;s create some!\"\n          actions={\n            <EuiButton size=\"s\" key=\"loadUsers\" onClick={this.loadUsers}>\n              Load Users\n            </EuiButton>\n          }\n        />\n      ),\n      selection: [],\n    };\n  }\n\n  loadUsers = () => {\n    this.setState({\n      message: 'Loading users...',\n      loading: true,\n      users: undefined,\n      error: undefined,\n    });\n    setTimeout(() => {\n      this.setState({\n        loading: false,\n        message: noItemsFoundMsg,\n        error: undefined,\n        users: store.users,\n      });\n    }, random.number({ min: 0, max: 3000 }));\n  };\n\n  loadUsersWithError() {\n    this.setState({\n      message: 'Loading users...',\n      loading: true,\n      users: undefined,\n      error: undefined,\n    });\n    setTimeout(() => {\n      this.setState({\n        loading: false,\n        error: 'ouch!... again... ',\n        users: undefined,\n        message: noItemsFoundMsg,\n      });\n    }, random.number({ min: 0, max: 3000 }));\n  }\n\n  renderToolsLeft() {\n    const selection = this.state.selection;\n\n    if (selection.length === 0) {\n      return;\n    }\n\n    const onClick = () => {\n      store.deleteUsers(...selection.map(user => user.id));\n      this.setState({ selection: [] });\n    };\n\n    return (\n      <EuiButton color=\"danger\" iconType=\"trash\" onClick={onClick}>\n        Delete {selection.length} Users\n      </EuiButton>\n    );\n  }\n\n  renderToolsRight() {\n    return [\n      <EuiButton\n        key=\"loadUsers\"\n        onClick={this.loadUsers.bind(this)}\n        isDisabled={this.state.loading}>\n        Load Users\n      </EuiButton>,\n      <EuiButton\n        key=\"loadUsersError\"\n        onClick={this.loadUsersWithError.bind(this)}\n        isDisabled={this.state.loading}>\n        Load Users (Error)\n      </EuiButton>,\n    ];\n  }\n\n  render() {\n    const columns = [\n      {\n        field: 'firstName',\n        name: 'First Name',\n        sortable: true,\n        truncateText: true,\n      },\n      {\n        field: 'lastName',\n        name: 'Last Name',\n        truncateText: true,\n      },\n      {\n        field: 'github',\n        name: 'Github',\n        render: username => (\n          <EuiLink href={`https://github.com/${username}`} target=\"_blank\">\n            {username}\n          </EuiLink>\n        ),\n      },\n      {\n        field: 'dateOfBirth',\n        name: 'Date of Birth',\n        dataType: 'date',\n        render: date => formatDate(date, 'dobLong'),\n        sortable: true,\n      },\n      {\n        field: 'nationality',\n        name: 'Nationality',\n        render: countryCode => {\n          const country = store.getCountry(countryCode);\n          return `${country.flag} ${country.name}`;\n        },\n      },\n      {\n        field: 'online',\n        name: 'Online',\n        dataType: 'boolean',\n        render: online => {\n          const color = online ? 'success' : 'danger';\n          const label = online ? 'Online' : 'Offline';\n          return <EuiHealth color={color}>{label}</EuiHealth>;\n        },\n        sortable: true,\n      },\n    ];\n\n    const search = {\n      toolsLeft: this.renderToolsLeft(),\n      toolsRight: this.renderToolsRight(),\n      box: {\n        incremental: true,\n      },\n      filters: [\n        {\n          type: 'is',\n          field: 'online',\n          name: 'Online',\n          negatedName: 'Offline',\n        },\n        {\n          type: 'field_value_selection',\n          field: 'nationality',\n          name: 'Nationality',\n          multiSelect: false,\n          options: store.countries.map(country => ({\n            value: country.code,\n            name: country.name,\n            view: `${country.flag} ${country.name}`,\n          })),\n        },\n      ],\n    };\n\n    const pagination = {\n      initialPageSize: 5,\n      pageSizeOptions: [3, 5, 8],\n    };\n\n    const selection = {\n      selectable: user => user.online,\n      selectableMessage: selectable =>\n        !selectable ? 'User is currently offline' : undefined,\n      onSelectionChange: selection => this.setState({ selection }),\n    };\n\n    return (\n      <div>\n        <EuiInMemoryTable\n          items={this.state.users}\n          itemId=\"id\"\n          error={this.state.error}\n          loading={this.state.loading}\n          message={this.state.message}\n          columns={columns}\n          search={search}\n          pagination={pagination}\n          sorting={true}\n          selection={selection}\n          isSelectable={true}\n        />\n      </div>\n    );\n  }\n}\n"